def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Extract opponent moves and outcomes
    opp = [h[1] for h in history]
    own = [h[0] for h in history]

    opp_def = 0
    for x in opp:
        if x == 'D':
            opp_def += 1
    own_def = 0
    for x in own:
        if x == 'D':
            own_def += 1

    last_opp = opp[-1]

    # Detect opponent behavior type.
    # If opponent has never defected, cooperate but probe rarely late.
    if opp_def == 0:
        if n >= 90 and rng.random() < 0.05:
            return 'D'
        return 'C'

    # If opponent always defects, defect.
    if opp_def == n:
        return 'D'

    # Look at recent window
    if n >= 10:
        recent = opp[-10:]
        recent_def = 0
        for x in recent:
            if x == 'D':
                recent_def += 1
    else:
        recent_def = opp_def

    # If opponent is almost fully cooperative recently, cooperate but
    # occasionally exploit when very safe (late in match).
    if recent_def <= 1:
        if n >= 95 and rng.random() < 0.5:
            return 'D'
        if n >= 50 and rng.random() < 0.08:
            return 'D'
        return 'C'

    # Sustained defection: punish hard.
    if recent_def >= 6:
        return 'D'

    # Respond to last move, but with forgiveness to recover cooperation.
    if last_opp == 'D':
        # Count consecutive tail defections
        streak = 0
        i = n - 1
        while i >= 0 and opp[i] == 'D':
            streak += 1
            i -= 1
        # If long defection streak, keep defecting
        if streak >= 3:
            return 'D'
        # Short defection: retaliate once, but with some forgiveness
        # to allow return to mutual cooperation.
        if streak == 1:
            # If opponent has been overall quite cooperative, sometimes forgive.
            if opp_def * 3 <= n and rng.random() < 0.35:
                return 'C'
            return 'D'
        # streak == 2
        if rng.random() < 0.15:
            return 'C'
        return 'D'
    else:
        # Opponent cooperated last round.
        # If we defected last round, cooperate to restore mutual cooperation.
        if own_def > 0 and own[-1] == 'D':
            return 'C'
        # Opponent mostly cooperative: cooperate.
        if opp_def * 2 <= n:
            return 'C'
        # Mixed: sometimes defect to keep them from exploiting.
        if rng.random() < 0.3:
            return 'D'
        return 'C'
